findings.call:
Spawn 8 threads, each calling `counter.increment()` 10,000 times concurrently. After all threads join, check if `counter.get() == 80_000`.

```rust
// Example trigger command/test setup
let counter = Arc::new(Counter::new());
let mut handles = vec![];
for _ in 0..8 {
    let c = Arc::clone(&counter);
    handles.push(std::thread::spawn(move || {
        for _ in 0..10_000 { c.increment(); }
    }));
}
for h in handles { h.join().unwrap(); }
assert_eq!(counter.get(), 80_000);
```
